 59	  /** merge multiple files together */
 60	  public static class Merge extends FsCommand {
 61	    public static final String NAME = "getmerge";    
 62	    public static final String USAGE = "[-nl] [-skip-empty-file] "
 63	        + "<src> <localdst>";
 64	    public static final String DESCRIPTION =
 65	        "Get all the files in the directories that "
 66	        + "match the source file pattern and merge and sort them to only "
 67	        + "one file on local fs. <src> is kept.\n"
 68	        + "-nl: Add a newline character at the end of each file.\n"
 69	        + "-skip-empty-file: Do not add new line character for empty file.";
 70	
 71	    protected PathData dst = null;
 72	    protected String delimiter = null;
 73	    private boolean skipEmptyFileDelimiter;
 74	    protected List<PathData> srcs = null;
 75	
 76	    @Override
 77	    protected void processOptions(LinkedList<String> args) throws IOException {
 78	      try {
 79	        CommandFormat cf = new CommandFormat(2, Integer.MAX_VALUE, "nl",
 80	            "skip-empty-file");
 81	        cf.parse(args);
 82	
 83	        delimiter = cf.getOpt("nl") ? "\n" : null;
 84	        skipEmptyFileDelimiter = cf.getOpt("skip-empty-file");
 85	
 86	        dst = new PathData(new URI(args.removeLast()), getConf());
 87	        if (dst.exists && dst.stat.isDirectory()) {
 88	          throw new PathIsDirectoryException(dst.toString());
 89	        }
 90	        srcs = new LinkedList<PathData>();
 91	      } catch (URISyntaxException e) {
 92	        throw new IOException("unexpected URISyntaxException", e);
 93	      }
 94	    }
 95	
 96	    @Override
 97	    protected void processArguments(LinkedList<PathData> items)
 98	    throws IOException {
 99	      super.processArguments(items);
100	      if (exitCode != 0) { // check for error collecting paths
101	        return;
102	      }
103	      FSDataOutputStream out = dst.fs.create(dst.path);
104	      try {
105	        for (PathData src : srcs) {
106	          if (src.stat.getLen() != 0) {
107	            try (FSDataInputStream in = src.fs.open(src.path)) {
108	              IOUtils.copyBytes(in, out, getConf(), false);
109	              writeDelimiter(out);
110	            }
111	          } else if (!skipEmptyFileDelimiter) {
112	            writeDelimiter(out);
113	          }
114	        }
115	      } finally {
116	        out.close();
117	      }
118	    }
119	
120	    private void writeDelimiter(FSDataOutputStream out) throws IOException {
121	      if (delimiter != null) {
122	        out.write(delimiter.getBytes("UTF-8"));
123	      }
124	    }
125	
126	    @Override
127	    protected void processNonexistentPath(PathData item) throws IOException {
128	      exitCode = 1; // flag that a path is bad
129	      super.processNonexistentPath(item);
130	    }
131	
132	    // this command is handled a bit differently than others.  the paths
133	    // are batched up instead of actually being processed.  this avoids
134	    // unnecessarily streaming into the merge file and then encountering
135	    // a path error that should abort the merge
136	    
137	    @Override
138	    protected void processPath(PathData src) throws IOException {
139	      // for directories, recurse one level to get its files, else skip it
140	      if (src.stat.isDirectory()) {
141	        if (getDepth() == 0) {
142	          recursePath(src);
143	        } // skip subdirs
144	      } else {
145	        srcs.add(src);
146	      }
147	    }
148	
149	    @Override
150	    protected boolean isSorted() {
151	      //Sort the children for merge
152	      return true;
153	    }
154	  }
