156	  static class Cp extends CommandWithDestination {
157	    public static final String NAME = "cp";
158	    public static final String USAGE =
159	        "[-f] [-p | -p[topax]] [-d] <src> ... <dst>";
160	    public static final String DESCRIPTION =
161	      "Copy files that match the file pattern <src> to a " +
162	      "destination.  When copying multiple files, the destination " +
163	      "must be a directory. Passing -p preserves status " +
164	      "[topax] (timestamps, ownership, permission, ACLs, XAttr). " +
165	      "If -p is specified with no <arg>, then preserves " +
166	      "timestamps, ownership, permission. If -pa is specified, " +
167	      "then preserves permission also because ACL is a super-set of " +
168	      "permission. Passing -f overwrites the destination if it " +
169	      "already exists. raw namespace extended attributes are preserved " +
170	      "if (1) they are supported (HDFS only) and, (2) all of the source and " +
171	      "target pathnames are in the /.reserved/raw hierarchy. raw namespace " +
172	      "xattr preservation is determined solely by the presence (or absence) " +
173	        "of the /.reserved/raw prefix and not by the -p option. Passing -d "+
174	        "will skip creation of temporary file(<dst>._COPYING_).\n";
175	
176	    @Override
177	    protected void processOptions(LinkedList<String> args) throws IOException {
178	      popPreserveOption(args);
179	      CommandFormat cf = new CommandFormat(2, Integer.MAX_VALUE, "f", "d");
180	      cf.parse(args);
181	      setDirectWrite(cf.getOpt("d"));
182	      setOverwrite(cf.getOpt("f"));
183	      // should have a -r option
184	      setRecursive(true);
185	      getRemoteDestination(args);
186	    }
187	    
188	    private void popPreserveOption(List<String> args) {
189	      for (Iterator<String> iter = args.iterator(); iter.hasNext(); ) {
190	        String cur = iter.next();
191	        if (cur.equals("--")) {
192	          // stop parsing arguments when you see --
193	          break;
194	        } else if (cur.startsWith("-p")) {
195	          iter.remove();
196	          if (cur.length() == 2) {
197	            setPreserve(true);
198	          } else {
199	            String attributes = cur.substring(2);
200	            for (int index = 0; index < attributes.length(); index++) {
201	              preserve(FileAttribute.getAttribute(attributes.charAt(index)));
202	            }
203	          }
204	          return;
205	        }
206	      }
207	    }
208	  }
