411	  /**
412	   *  Append the contents of one or more local files to a remote
413	   *  file.
414	   */
415	  public static class AppendToFile extends CommandWithDestination {
416	    public static final String NAME = "appendToFile";
417	    public static final String USAGE = "<localsrc> ... <dst>";
418	    public static final String DESCRIPTION =
419	        "Appends the contents of all the given local files to the " +
420	            "given dst file. The dst file will be created if it does " +
421	            "not exist. If <localSrc> is -, then the input is read " +
422	            "from stdin.";
423	
424	    private static final int DEFAULT_IO_LENGTH = 1024 * 1024;
425	    boolean readStdin = false;
426	
427	    // commands operating on local paths have no need for glob expansion
428	    @Override
429	    protected List<PathData> expandArgument(String arg) throws IOException {
430	      List<PathData> items = new LinkedList<PathData>();
431	      if (arg.equals("-")) {
432	        readStdin = true;
433	      } else {
434	        try {
435	          items.add(new PathData(new URI(arg), getConf()));
436	        } catch (URISyntaxException e) {
437	          if (Path.WINDOWS) {
438	            // Unlike URI, PathData knows how to parse Windows drive-letter paths.
439	            items.add(new PathData(arg, getConf()));
440	          } else {
441	            throw new IOException("Unexpected URISyntaxException: " + e.toString());
442	          }
443	        }
444	      }
445	      return items;
446	    }
447	
448	    @Override
449	    protected void processOptions(LinkedList<String> args)
450	        throws IOException {
451	
452	      if (args.size() < 2) {
453	        throw new IOException("missing destination argument");
454	      }
455	
456	      getRemoteDestination(args);
457	      super.processOptions(args);
458	    }
459	
460	    @Override
461	    protected void processArguments(LinkedList<PathData> args)
462	        throws IOException {
463	
464	      if (!dst.exists) {
465	        dst.fs.create(dst.path, false).close();
466	      }
467	
468	      InputStream is = null;
469	      try (FSDataOutputStream fos = dst.fs.append(dst.path)) {
470	        if (readStdin) {
471	          if (args.size() == 0) {
472	            IOUtils.copyBytes(System.in, fos, DEFAULT_IO_LENGTH);
473	          } else {
474	            throw new IOException(
475	                "stdin (-) must be the sole input argument when present");
476	          }
477	        }
478	
479	        // Read in each input file and write to the target.
480	        for (PathData source : args) {
481	          is = Files.newInputStream(source.toFile().toPath());
482	          IOUtils.copyBytes(is, fos, DEFAULT_IO_LENGTH);
483	          IOUtils.closeStream(is);
484	          is = null;
485	        }
486	      } finally {
487	        if (is != null) {
488	          IOUtils.closeStream(is);
489	        }
490	      }
491	    }
492	  }
